const { EventEmitter } = require('events')
const e = new EventEmitter()
e.on('x', () => console.log(1))
e.prependListener('x', () => console.log(2))
e.emit('x')

const { EventEmitter } = require('events')
const e = new EventEmitter()
const f = () => console.log(1)
e.on('x', f)
e.off('x', f)
e.emit('x')
console.log(2)

const { EventEmitter } = require('events')
const e = new EventEmitter()
try {
  e.emit('error', new Error('x'))
  console.log(1)
} catch {
  console.log(2)
}

const path = require('path')
console.log(path.posix.isAbsolute('/a') ? 1 : 0)
console.log(path.posix.isAbsolute('a') ? 1 : 0)

let n = 0
function f() {
  console.log(n)
  n += 1
  if (n < 3) process.nextTick(f)
}
process.nextTick(f)
setImmediate(() => console.log(9))

setImmediate(() => {
  console.log(1)
  setImmediate(() => console.log(2))
})

const { Readable } = require('stream')
const r = Readable.from(['1', '2'])
r.on('data', (chunk) => console.log(String(chunk)))

const { Transform } = require('stream')
const t = new Transform({
  transform(chunk, _enc, cb) {
    cb(null, String(Number(chunk) + 1))
  },
})
t.on('data', (chunk) => console.log(String(chunk)))
t.write('3')
t.end()

