const e = new EventEmitter()
e.on('x', () => {})
e.on('x', () => {})
e.removeAllListeners('x')
console.log(e.listenerCount('x'))

const src = Buffer.from('ab')
const dst = Buffer.alloc(2)
src.copy(dst)
console.log(dst.toString())

const { types } = require('util')
console.log(types.isDate(new Date()) ? 1 : 0)
console.log(types.isDate({}) ? 1 : 0)

const { PassThrough } = require('stream')
const p = new PassThrough()
p.on('data', (chunk) => console.log(String(chunk)))
p.write('5')
p.end()

